#!/usr/bin/env node
/**
 * Syncs the job-tracker-api OpenAPI contract into this app.
 *
 * The backend repo (`job-tracker-api`) is the single source of truth: its
 * committed `openapi.json` is regenerated by `scripts/export_openapi.py`
 * whenever the API surface changes. This script mirrors that file into
 * `contract/openapi.json` and regenerates `src/services/api/generated/
 * openapi.ts` (TypeScript types via openapi-typescript). The generated
 * types are aliased by `src/services/types/*`, so contract drift surfaces
 * as compile errors instead of runtime surprises.
 *
 * Usage:
 *   node scripts/sync-api-contract.mjs                 # sync from sibling repo
 *   node scripts/sync-api-contract.mjs --from <path|url>
 *   node scripts/sync-api-contract.mjs --api-repo <path-to-job-tracker-api>
 *   node scripts/sync-api-contract.mjs --check         # verify committed artifacts are fresh
 */
import { execFileSync } from 'node:child_process';
import {
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const APP_ROOT = fileURLToPath(new URL('..', import.meta.url));
const REPO_ROOT = join(APP_ROOT, '..', '..');
const SPEC_TARGET = join(APP_ROOT, 'contract', 'openapi.json');
const TYPES_TARGET = join(
  APP_ROOT,
  'src',
  'services',
  'api',
  'generated',
  'openapi.ts',
);
// career-hub and job-tracker-api are sibling checkouts under the same parent.
const DEFAULT_SPEC_SOURCE = join(
  REPO_ROOT,
  '..',
  'job-tracker-api',
  'openapi.json',
);

function parseArgs(argv) {
  const args = { check: false, from: null, apiRepo: null };
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '--check') {
      args.check = true;
    } else if (arg === '--from' || arg === '--api-repo') {
      i += 1;
      if (arg === '--from') {
        args.from = argv[i];
      } else {
        args.apiRepo = argv[i];
      }
    } else {
      throw new Error(`Unknown argument: ${arg}`);
    }
  }
  return args;
}

function resolveSpecPath(args) {
  if (args.from) return args.from;
  if (args.apiRepo) {
    return args.apiRepo.endsWith('.json')
      ? args.apiRepo
      : join(args.apiRepo, 'openapi.json');
  }
  return DEFAULT_SPEC_SOURCE;
}

async function loadSpec(source) {
  if (/^https?:\/\//.test(source)) {
    const response = await fetch(source);
    if (!response.ok) {
      throw new Error(`Failed to fetch ${source}: HTTP ${response.status}`);
    }
    return Buffer.from(await response.arrayBuffer());
  }
  return readFileSync(source);
}

// Invoke the package CLIs through node directly — .cmd shims can't be
// execFile'd on Windows without a shell.
const OPENAPI_TS_CLI = join(
  REPO_ROOT,
  'node_modules',
  'openapi-typescript',
  'bin',
  'cli.js',
);
const PRETTIER_CLI = join(
  REPO_ROOT,
  'node_modules',
  'prettier',
  'bin',
  'prettier.cjs',
);

function runPrettier(file) {
  execFileSync(
    process.execPath,
    // --config pins resolution: in --check mode the output lives in a temp
    // dir outside the repo, where prettier would find no config.
    [PRETTIER_CLI, '--write', '--config', join(REPO_ROOT, '.prettierrc'), file],
    { cwd: REPO_ROOT, stdio: 'inherit' },
  );
}

function generateTypes(specPath, outPath) {
  execFileSync(
    process.execPath,
    // --default-non-nullable=false keeps fields with server-side defaults
    // optional in request bodies (Pydantic applies the default when omitted).
    [
      OPENAPI_TS_CLI,
      specPath,
      '-o',
      outPath,
      '--default-non-nullable',
      'false',
    ],
    { cwd: REPO_ROOT, stdio: 'inherit' },
  );
  runPrettier(outPath);
}

function diffBytes(label, expectedPath, actual) {
  let expected;
  try {
    expected = readFileSync(expectedPath);
  } catch {
    console.error(`${label} is missing: ${expectedPath}`);
    return false;
  }
  if (!expected.equals(actual)) {
    console.error(`${label} is stale: ${expectedPath}`);
    return false;
  }
  return true;
}

const args = parseArgs(process.argv.slice(2));
const source = resolveSpecPath(args);
const spec = await loadSpec(source);

if (args.check) {
  const tmp = mkdtempSync(join(tmpdir(), 'api-contract-'));
  try {
    const tmpSpec = join(tmp, 'openapi.json');
    const tmpTypes = join(tmp, 'openapi.ts');
    writeFileSync(tmpSpec, spec);
    generateTypes(tmpSpec, tmpTypes);
    let ok = diffBytes('contract/openapi.json', SPEC_TARGET, spec);
    ok =
      diffBytes(
        'src/services/api/generated/openapi.ts',
        TYPES_TARGET,
        readFileSync(tmpTypes),
      ) && ok;
    if (!ok) {
      console.error(
        '\nContract artifacts are stale. Run `npm run sync:api-contract` ' +
          '(source: ' +
          source +
          ') and commit the result.',
      );
      process.exit(1);
    }
    console.log('API contract artifacts are up to date.');
  } finally {
    rmSync(tmp, { recursive: true, force: true });
  }
} else {
  mkdirSync(join(APP_ROOT, 'contract'), { recursive: true });
  mkdirSync(join(APP_ROOT, 'src', 'services', 'api', 'generated'), {
    recursive: true,
  });
  writeFileSync(SPEC_TARGET, spec);
  generateTypes(SPEC_TARGET, TYPES_TARGET);
  console.log(`Synced API contract from ${source}`);
}
